void gsKnotVector<T>::trim(int i)
{
    std::transform(m_mult_sum.begin(), m_mult_sum.end(), m_mult_sum.begin(),
                   std::bind2nd(std::minus<unsigned>(), i) );
    m_mult_sum.back() -= i;
}

