                        tmp_basis2ndDerivs(0,1) = basis2ndDerivs(fct_i*d2_offsetter+2, k);
                        tmp_basis2ndDerivs(1,0) = basis2ndDerivs(fct_i*d2_offsetter+2, k);
                        tmp_basis2ndDerivs(1,1) = basis2ndDerivs(fct_i*d2_offsetter+1, k);
                    }
