    typedef std::vector<index_t>::const_iterator citer;
    citer istart = m_dofs[0].begin() + m_offset[k];
    citer iend   = istart + patchSize(k);
    return find_impl(istart, iend, GS_BIND2ND(std::greater<index_t>(),s));
}

