    {
         res.resize(2,1); // [dMeasure/dxi, dMeasure/deta]

        grad = _G.data().values[1].reshapeCol(k, _G.data().dim.first, _G.data().dim.second).transpose();

        // dG/dxi x dG/deta
        cross = grad.col(0).cross(grad.col(1));
